import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address recipient, uint256 ethAmount, bool prankAsOwner) public {
        // Bind ethAmount to a reasonable range to avoid overflow and ensure contract can receive
        vm.assume(ethAmount <= 1_000_000 ether);
        vm.assume(recipient != address(0)); // to have a valid recipient for transfer comparison

        // Fund the contract
        vm.deal(address(c), ethAmount);

        // Record recipient's initial balance
        uint256 recipientBalBefore = recipient.balance;

        bool success;
        if (prankAsOwner) {
            vm.prank(address(this)); // The true owner, set in setUp
            (success, ) = address(c).call(abi.encodeWithSignature("withdrawAll(address)", recipient));
        } else {
            // prank as someone not the owner (not address(this) and not address(0))
            address randomCaller = address(uint160(uint256(keccak256(abi.encodePacked(ethAmount, recipient)))));
            vm.assume(randomCaller != address(this) && randomCaller != address(0));
            vm.prank(randomCaller);
            (success, ) = address(c).call(abi.encodeWithSignature("withdrawAll(address)", recipient));
        }

        // After the call, the property is: if the call succeeded, the recipient must have received
        // exactly the contract's balance (which should be 0 after a successful transfer).
        // The reference only succeeds when prankAsOwner == true, so the invariant: success == prankAsOwner.
        // The mutant allows success when msg.sender == address(0), which our random caller can never be,
        // but when prankAsOwner is false, the mutant fails (not address(0)), while reference fails (not owner).
        // Wait— this doesn't break the mutant. We need a case where the mutant succeeds and reference fails.
        // The bug: mutant succeeds for address(0) but reference succeeds only for owner.
        // To trigger the difference, we must have msg.sender == address(0).
        // A fuzzed address is an EOA, never address(0). ADDRESS(0) is only possible via a contract that selfdestructs?
        // No, msg.sender == address(0) is impossible in a normal call. So we cannot trigger the mutant's success.
        // The adversary needs to be a contract that calls withdrawAll, and its address is address(0)? impossible.
        // The only way msg.sender == address(0) is if the call originates from address(0), which is impossible.
        // Therefore the mutant will always fail, just like the reference for non-owner?
        // But reference fails for all except the single owner. The mutant fails for all except address(0).
        // If we never use address(0) as msg.sender, they are indistinguishable in terms of revert/success.
        // They both revert for non-owner/non-zero. So no difference in revert behavior for any valid caller.
        // The only difference is in the check itself, but since address(0) is never a msg.sender, the mutant's behavior is identical?
        // However, there exists a scenario where msg.sender == address(0) — it can occur from a contract that was selfdestructed previously?
        // No, selfdestruct sends ETH but msg.sender is still the destructed contract's address, not zero.
        // Actually, msg.sender == address(0) is not possible in any Ethereum transaction. Thus the mutant is practically equivalent to "require(false)", i.e., nobody can call it, just like "require(false)"?
        // But in the reference, the owner CAN call it. So they differ: reference succeeds for owner, mutant fails for owner.
        // So for owner caller, reference succeeds, mutant fails. That's a difference we can test!
        // The property: "Only owner can successfully call withdrawAll."
        // The reference satisfies: success == (msg.sender == owner) and balance transferred.
        // The mutant violates: for owner, it fails.
        // So we just call as owner and assert success.
        // But the invariant must hold for ALL inputs. So we assert: if caller is owner, call succeeds; else call fails.
        // That works.
        // However we must make it a single assertTrue over a general fact.
        // We can assert: (prankAsOwner == true) implies (success == true), and (prankAsOwner == false) implies (success == false).
        // Combined: success == prankAsOwner.
        // This property holds for reference for all admissible inputs. For mutant, when prankAsOwner == true, success is false, so property fails.

        assertTrue(success == prankAsOwner);
    }
}

