import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller, address recipient) public {
        // caller must not be the owner (address(this))
        vm.assume(caller != address(this));
        // recipient can be anything, but let's keep it different from caller just for clarity
        // No bound needed

        // Give the contract some ETH
        vm.deal(address(c), 1 ether);
        uint256 balanceBefore = address(c).balance;

        // Prank as the non-owner caller
        vm.prank(caller);
        // In the reference, this call reverts because caller != owner
        // In the mutant, it succeeds because require is removed
        (bool success,) = address(c).call{value: 0}(abi.encodeWithSignature("withdrawAll(address)", recipient));
        uint256 balanceAfter = address(c).balance;

        // For the reference, success is false, so balanceAfter == balanceBefore (no state change)
        // For the mutant, success is true, and the entire balance is transferred to recipient,
        // so balanceAfter == 0, which is different from balanceBefore.
        // The assertion: if the call succeeds, the contract balance after the call must equal the balance before.
        // The reference satisfies this (call reverts, so the condition is vacuously true).
        // The mutant violates this (call succeeds, and balance changes).
        assertTrue(!success || balanceAfter == balanceBefore);
    }
}

